<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import {usePermission} from '@/composables/permission';
import {getAutomaticRetry,configureAutomaticRetry,enableAutomaticRetry,validateAutomaticRetry,type AutomaticRetryPolicy,type AutomaticRetryState} from '@/api/automatic-retry';
import type {InspectionTask} from '@/api/tasks';
import AutomaticRetryPolicyEditor from './AutomaticRetryPolicyEditor.vue';
const props=defineProps<{task:InspectionTask}>();
const emit=defineEmits<{(e:'updated',value:AutomaticRetryState):void}>();
const {can}=usePermission();
const state=ref<AutomaticRetryState>(),policy=ref<AutomaticRetryPolicy|null>(null),busy=ref(false),error=ref('');let generation=0;
const configurable=computed(()=>!!state.value&&props.task.taskType==='PIPELINE'&&props.task.status==='CREATED'&&!props.task.currentExecutionId&&!(props.task.attemptCount??0)&&!state.value?.policyHash&&can('iqc:task:retry-policy:configure'));
const enableAllowed=computed(()=>!['CANCELLED','SUCCEEDED','DELETED'].includes(props.task.status));
async function load(){const ticket=++generation;state.value=undefined;policy.value=null;error.value='';if(!can('iqc:task:retry-policy:view')){busy.value=false;return;}busy.value=true;try{const value=await getAutomaticRetry(props.task.id);if(ticket===generation){state.value=value;policy.value=value.policy?{...value.policy}:null;}}catch{if(ticket===generation)error.value='自动重试策略加载失败，请重试。';}finally{if(ticket===generation)busy.value=false;}}
async function save(){if(busy.value||!configurable.value)return;let value:AutomaticRetryPolicy|null;try{value=validateAutomaticRetry(policy.value);if(!value)throw Error('请选择自动重试策略后冻结');}catch(e){error.value=e instanceof Error?e.message:'策略无效';return;}const ticket=generation,id=props.task.id;busy.value=true;try{const result=await configureAutomaticRetry(id,value);if(ticket===generation){state.value=result;policy.value=result.policy?{...result.policy}:null;emit('updated',result);}}catch{if(ticket===generation)error.value='配置未确认，请重新加载核对。';}finally{if(ticket===generation)busy.value=false;}}
async function availability(){const previous=state.value;if(busy.value||!previous?.policyHash||!can('iqc:task:retry-policy:availability')||(!previous.enabled&&!enableAllowed.value))return;const ticket=generation;busy.value=true;try{const value=await enableAutomaticRetry(props.task.id,!previous.enabled);if(ticket===generation){state.value=value;emit('updated',value);}}catch{if(ticket===generation)error.value='启停未确认，请重新加载核对。';}finally{if(ticket===generation)busy.value=false;}}
watch([()=>props.task.id,()=>props.task.status,()=>props.task.retryPolicyHash,()=>props.task.automaticRetryEnabled,()=>can('iqc:task:retry-policy:view'),()=>can('iqc:task:retry-policy:configure'),()=>can('iqc:task:retry-policy:availability')],()=>void load(),{immediate:true});onBeforeUnmount(()=>{++generation;});
</script>
<template><section v-if="can('iqc:task:retry-policy:view')"><a-space><h3>自动重试</h3><a-button :disabled="busy" @click="load">重新加载</a-button></a-space><a-alert v-if="error" type="error" :message="error"/><a-alert type="info" message="策略冻结后仅能启停。初次及手动轮次计入总上限，自动队列使用原冻结数据和版本。"/><a-form layout="vertical"><AutomaticRetryPolicyEditor v-model="policy" :disabled="busy||!configurable"/><a-button v-if="configurable" type="primary" :disabled="busy||!policy" @click="save">冻结策略</a-button></a-form><a-descriptions v-if="state" :column="1"><a-descriptions-item label="状态">{{state.enabled?'已启用':'已停用'}}</a-descriptions-item><a-descriptions-item label="策略指纹">{{state.policyHash||'尚未配置'}}</a-descriptions-item><a-descriptions-item label="最早重试 UTC">{{state.nextRetryAtUtc||'无'}}</a-descriptions-item><a-descriptions-item v-if="state.error" label="未重试原因">{{state.error==='TOOL_SIDE_EFFECT_REQUIRES_REVIEW'?'工具可能已执行，已停止自动重试；请核对外部工具结果。':state.error}}</a-descriptions-item></a-descriptions><a-button v-if="state?.policyHash&&can('iqc:task:retry-policy:availability')" :disabled="busy||(!state.enabled&&(!enableAllowed||state.error==='TOOL_SIDE_EFFECT_REQUIRES_REVIEW'))" @click="availability">{{state.enabled?'停用自动重试':'启用自动重试'}}</a-button></section></template>
